import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import { Agent, createTool } from "@voltagent/core";
import { VercelAIProvider } from "@voltagent/vercel-ai";
import { openai } from "@ai-sdk/openai";
import { convertJsonSchemaToZod } from "zod-from-json-schema";

let agent = null;
let mathClient = null;
let stringClient = null;

async function initAgent() {
  if (agent) return agent;

  // Initialize and connect to math server
  mathClient = new Client(
    { name: "math-client", version: "1.0.0" },
    { capabilities: {} }
  );
  const mathTransport = new StdioClientTransport({
    command: "node",
    args: ["/home/user/servers/math-server.js"],
  });
  await mathClient.connect(mathTransport);

  // Initialize and connect to string server
  stringClient = new Client(
    { name: "string-client", version: "1.0.0" },
    { capabilities: {} }
  );
  const stringTransport = new StdioClientTransport({
    command: "node",
    args: ["/home/user/servers/string-server.js"],
  });
  await stringClient.connect(stringTransport);

  // Retrieve tools from both servers
  const mathToolsResponse = await mathClient.listTools();
  const stringToolsResponse = await stringClient.listTools();

  const voltAgentTools = [];

  // Map math tools to VoltAgent tools
  for (const toolDef of mathToolsResponse.tools) {
    voltAgentTools.push(createTool({
      name: toolDef.name,
      description: toolDef.description,
      parameters: convertJsonSchemaToZod(toolDef.inputSchema),
      execute: async (args) => {
        const result = await mathClient.callTool({
          name: toolDef.name,
          arguments: args,
        });
        // Assuming the result is text-based as per the server implementation
        return result.content[0].text;
      },
    }));
  }

  // Map string tools to VoltAgent tools
  for (const toolDef of stringToolsResponse.tools) {
    voltAgentTools.push(createTool({
      name: toolDef.name,
      description: toolDef.description,
      parameters: convertJsonSchemaToZod(toolDef.inputSchema),
      execute: async (args) => {
        const result = await stringClient.callTool({
          name: toolDef.name,
          arguments: args,
        });
        return result.content[0].text;
      },
    }));
  }

  // Create the VoltAgent Agent
  agent = new Agent({
    name: "mcp-agent",
    instructions: "You are a helpful assistant equipped with math and string manipulation tools. Use them whenever needed to answer the user's request.",
    model: openai("gpt-4o-mini"),
    tools: voltAgentTools,
  });

  return agent;
}

/**
 * Runs the agent with the given prompt.
 * @param {string} prompt - The user prompt.
 * @returns {Promise<string>} - The agent's response text.
 */
export async function runAgent(prompt) {
  const agentInstance = await initAgent();
  const response = await agentInstance.generateText(prompt, {
    provider: new VercelAIProvider(),
  });
  return response.text;
}

